void compute(const std::string& chars, std::ostream& output) {
    int position = 0;
    int maxSegment = 0;
    int pairs = 0;
    bool inside = false;
    int length = chars.length();

    while (position < length) {
        if (chars[position] == '(') {
            inside = true;
        } else if (chars[position] == ')') {
            inside = false;
        } else if (isalpha(chars[position])) {
            position--;
        }
        if (inside) {
            while (++position != length && chars[position] != ')' && !isalpha(chars[position]));
            if (position == length || !isalpha(chars[position])) {
                continue;
            }
            while (++position != length && isalpha(chars[position]));
            pairs++;
        } else {
            while (++position != length && chars[position] != '(' && !isalpha(chars[position]));
            if (position == length || !isalpha(chars[position])) {
                continue;
            }
            int startIdx = position;
            while (++position != length && isalpha(chars[position]));
            maxSegment = std::max(maxSegment, position - startIdx);
        }
    }
    output << maxSegment << " " << pairs << "\n";
}

